import hashlib, importlib.util, json, os, signal, statistics, subprocess, sys, time, uuid
from pathlib import Path
root=Path('/data/git/gleditor-restore')
outdir=root/'build/performance/comparisons/m3-c2-thinlto-interleaved'
if outdir.exists():sys.exit('refusing to overwrite interleaved comparison')
outdir.mkdir(parents=True)
spec=importlib.util.spec_from_file_location('perf_focus',root/'tools/performance-report.py')
p=importlib.util.module_from_spec(spec);spec.loader.exec_module(p)
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
variants={}
for label in ['p3-baseline-thinlto','hybrid-unordered-c2']:
 base=root/'build/performance/variants'/('m3-'+label)
 manifest=json.loads((base/'artifact-manifest.json').read_text())
 timing=json.loads((base/'timing.json').read_text()) if label!='p3-baseline-thinlto' else None
 expected={r['path']:r['sha256'] for r in manifest['artifacts']}
 (base/'bin').mkdir(exist_ok=True)
 bins={}
 for name in ['performance-probe','performance-probe-counts']:
  path=base/'bin'/name
  if label=='hybrid-unordered-c2':
   import shutil
   assert sha(root/'build'/name)==expected['build/'+name]
   shutil.copy2(root/'build'/name,path)
  assert sha(path)==expected['build/'+name]
  if label=='p3-baseline-thinlto':
   original=next(x for x in json.loads((base/'restoration.json').read_text())['probes'] if x['name']==name)
  else:
   original=next((w['command_identity'] for w in timing['workloads'] if w['command_identity']['argv'][0]=='build/'+name),None)
   if original is None:original=next(w['counter_command_identity'] for w in timing['workloads'] if w.get('counter_command_identity',{}).get('argv',[None])[0]=='build/'+name)
  actual=p.command_identity([str(path)])
  assert actual['libraries']==original['libraries']
  assert all(not str(x['path']).startswith(str(root)) for x in actual['libraries'])
  assert 'not found' not in subprocess.check_output(['ldd',str(path)],text=True)
  bins[name]={'path':str(path),'sha256':expected['build/'+name],'libraries':actual['libraries']}
 variants[label]={'source':manifest['source'],'manifest_sha256':sha(base/'artifact-manifest.json'),'compiler':manifest['compiler'],'buildflags':manifest['buildflags'],'bins':bins}
assert variants['p3-baseline-thinlto']['compiler']==variants['hybrid-unordered-c2']['compiler']
assert variants['p3-baseline-thinlto']['buildflags']==variants['hybrid-unordered-c2']['buildflags']
assert variants['p3-baseline-thinlto']['bins']['performance-probe']['libraries']==variants['hybrid-unordered-c2']['bins']['performance-probe']['libraries']
affinity=sorted(os.sched_getaffinity(0));cpu=affinity[0]
report={'schema_version':1,'variants':variants,'cpu':cpu,'allowed_affinity':affinity,'scope':'Shared-host, CPU-pinned rotating/reversing temporal blocks; fold timer excludes setup, linked timer excludes construction; process RSS includes startup/setup. No dedicated-host or universal causal claim.','resource_wrapper_sha256':sha(Path('/tmp/performance-stage-resources.py')),'samples':[]}
path=outdir/'report.json'
folds=[(s,n) for s in ['fold-text','fold-structure','fold-branch'] for n in [144,1000,10000]]
links=[('arena-link-'+s,144) for s in ['local','base','quote-local','quote-extern','proxy']]
cases=folds+links
costs={'wall_time_ns','fold_kernel_ns','scenario_total_cpp_new_calls','scenario_total_cpp_new_requested_bytes','fold_cpp_new_calls','fold_cpp_new_requested_bytes','by_ref_index_scan_ns','p3_link_traversal_ns'}
def save():path.write_text(json.dumps(report,indent=2)+'\n')
def run(label,scenario,size,phase,index,measure):
 name='performance-probe-counts' if measure=='allocations' else 'performance-probe'
 artifact=variants[label]['bins'][name]
 assert sha(Path(artifact['path']))==artifact['sha256']
 case=f'{scenario}-{size}-{phase}-{index}-{label}'
 data=outdir/'xdg'/case;env=p.headless_environment(os.environ)
 for key,leaf in [('XDG_DATA_HOME','data'),('XDG_CONFIG_HOME','config'),('XDG_CACHE_HOME','cache')]:
  d=data/leaf;d.mkdir(parents=True);env[key]=str(d)
 argv=[artifact['path'],'--scenario',scenario,'--size',str(size),'--seed','9501','--measure',measure]
 resource_path=outdir/(case+'.resources.json')
 cmd=['python3','/tmp/performance-stage-resources.py',str(resource_path)]+argv
 started=time.perf_counter()
 proc=subprocess.Popen(cmd,cwd=root,env=env,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True,preexec_fn=lambda:os.sched_setaffinity(0,{cpu}))
 try:stdout,stderr=proc.communicate(timeout=60)
 except subprocess.TimeoutExpired:
  os.killpg(proc.pid,signal.SIGKILL);stdout,stderr=proc.communicate();raise RuntimeError('timed out '+case)
 (outdir/(case+'.stdout')).write_text(stdout);(outdir/(case+'.stderr')).write_text(stderr)
 if proc.returncode:raise RuntimeError('probe failed '+case+' '+stderr)
 metrics=json.loads(stdout);resource=json.loads(resource_path.read_text())
 assert metrics['scenario']==scenario and metrics['size']==size and metrics['measure']==measure and metrics['seed']==9501
 key='fold_kernel_ns' if scenario.startswith('fold-') else 'p3_link_traversal_ns'
 if measure=='timing':assert isinstance(metrics[key],int) and metrics[key]>0
 sample={'variant':label,'scenario':scenario,'size':size,'phase':phase,'index':index,'measure':measure,'selected_metric':key,'selected_ns':metrics[key] if measure=='timing' else None,'metrics':metrics,'resources':resource,'wrapper_elapsed_seconds':time.perf_counter()-started,'load_average_after':os.getloadavg(),'argv':argv,'success':True}
 report['samples'].append(sample);save();print(case,round(sample['wrapper_elapsed_seconds'],3),flush=True)
 return {k:v for k,v in metrics.items() if k not in costs}
try:
 for c,(scenario,size) in enumerate(cases):
  for phase,index in [('warmup',0)]+[('run',i) for i in range(1,8)]:
   order=['p3-baseline-thinlto','hybrid-unordered-c2']
   rotation=(c+index)%len(order)
   order=order[rotation:]+order[:rotation]
   if ((c+index)//len(order))%2:order.reverse()
   semantics=[run(label,scenario,size,phase,index,'timing') for label in order]
   assert all(value==semantics[0] for value in semantics),f'work differs {scenario} {size}'
  semantics=[run(label,scenario,size,'counter',1,'allocations') for label in variants]
  assert all(value==semantics[0] for value in semantics),f'counter work differs {scenario} {size}'
 report['artifacts_unchanged']=all(sha(Path(a['path']))==a['sha256'] for v in variants.values() for a in v['bins'].values())
 report['success']=report['artifacts_unchanged'];save()
except BaseException as error:
 report['success']=False;report['error']=str(error);save();raise

import hashlib,itertools,json,random,statistics
from pathlib import Path
p=Path('/data/git/gleditor-restore/build/performance/comparisons/m3-c2-thinlto-interleaved/report.json')
d=json.loads(p.read_text());assert d['success'] and d['artifacts_unchanged'] and len(d['samples'])==252
labels=list(d['variants']);rng=random.Random(20261116);rows=[]
for scenario,size in sorted({(s['scenario'],s['size']) for s in d['samples']}):
 ss=[s for s in d['samples'] if s['scenario']==scenario and s['size']==size]
 groups={i:{s['variant']:s for s in ss if s['phase']=='run' and s['index']==i} for i in range(1,8)}
 assert all(set(g)==set(labels) for g in groups.values())
 row={'scenario':scenario,'size':size,'selected_metric':ss[0]['selected_metric'],'variants':{},'comparisons':[]}
 for label in labels:
  timing=[groups[i][label] for i in range(1,8)];counter=next(s for s in ss if s['phase']=='counter' and s['variant']==label)
  row['variants'][label]={'median_selected_ns':statistics.median(s['selected_ns'] for s in timing),'selected_ns':[s['selected_ns'] for s in timing],'median_whole_scenario_ns':statistics.median(s['metrics']['wall_time_ns'] for s in timing),'median_probe_peak_rss_kib':statistics.median(s['resources']['maximum_child_rss_kib'] for s in timing),'counter_metrics':counter['metrics']}
 for baseline,candidate in itertools.combinations(labels,2):
  a=row['variants'][baseline]['selected_ns'];b=row['variants'][candidate]['selected_ns'];ratios=[]
  for _ in range(20000):
   indices=rng.choices(range(7),k=7);ratios.append(statistics.median(b[i] for i in indices)/statistics.median(a[i] for i in indices))
  ratios.sort();row['comparisons'].append({'baseline':baseline,'candidate':candidate,'candidate_over_baseline_median_ratio':statistics.median(b)/statistics.median(a),'temporal_block_bootstrap_95pct_ci':[ratios[500],ratios[19500]]})
 rows.append(row)
out={'source_report_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'success':True,'samples':len(d['samples']),'method':'20,000 paired temporal-block bootstrap draws per fixed case and variant pair; seven measured repetitions per side; rotating/reversing order; CPU pinned; shared host conditional observations; unadjusted intervals for exploratory comparisons, no universal causality or application aggregate','cpu':d['cpu'],'rows':rows}
p.with_name('analysis.json').write_text(json.dumps(out,indent=2)+'\n')
for r in rows:
 print(r['scenario'],r['size'],[(c['candidate']+'/'+c['baseline'],round(c['candidate_over_baseline_median_ratio'],3),[round(x,3) for x in c['temporal_block_bootstrap_95pct_ci']]) for c in r['comparisons']])

